import { z } from "zod";

const timestamp = z.string().datetime({ offset: true }).transform(value => new Date(value).toISOString());
const label = z.string().trim().min(1).max(200);
const shape = {
  project_id: z.string().trim().min(1).nullable().default(null),
  kind: z.enum(["observation", "fact", "commitment", "retraction", "resolution"]),
  text: z.string().min(1).max(20000).refine(value => value.trim().length > 0, "text must not be blank"),
  fact_key: label.optional(),
  evidence: z.enum(["self_reported", "operator_confirmed", "observed", "inferred", "legacy"]),
  source: label,
  source_ref: z.string().min(1).max(2000).optional(),
  occurred_at: timestamp.optional(),
  valid_from: timestamp.optional(),
  valid_until: timestamp.optional(),
  supersedes_id: z.string().uuid().optional(),
  target_id: z.string().uuid().optional(),
  owner: z.enum(["praxis", "member"]).optional(),
  due_at: timestamp.optional(),
  outcome: z.enum(["completed", "cancelled"]).optional(),
  idempotency_key: label.optional(),
};
const inputObject = z.object(shape).strict();
type Fields = z.infer<typeof inputObject>;

function validateKind(value: Fields, ctx: z.RefinementCtx) {
  const required: Record<Fields["kind"], string[]> = {
    observation: [], fact: ["fact_key"], commitment: ["owner"],
    retraction: ["target_id"], resolution: ["target_id", "outcome"],
  };
  const permitted: Record<Fields["kind"], string[]> = {
    observation: [], fact: ["fact_key", "supersedes_id", "valid_from", "valid_until"],
    commitment: ["owner", "due_at"], retraction: ["target_id"], resolution: ["target_id", "outcome"],
  };
  for (const key of ["fact_key", "supersedes_id", "valid_from", "valid_until", "owner", "due_at", "target_id", "outcome"] as const) {
    if (value[key] !== undefined && !permitted[value.kind].includes(key)) {
      ctx.addIssue({ code: z.ZodIssueCode.custom, path: [key], message: `${key} is not supported for ${value.kind}` });
    }
    if (value[key] === undefined && required[value.kind].includes(key)) {
      ctx.addIssue({ code: z.ZodIssueCode.custom, path: [key], message: `${key} is required for ${value.kind}` });
    }
  }
  if (value.valid_from && value.valid_until && value.valid_until <= value.valid_from) {
    ctx.addIssue({ code: z.ZodIssueCode.custom, path: ["valid_until"], message: "valid_until must be after valid_from" });
  }
}

/** New assertions must declare their provenance; legacy is reserved for migration. */
export const MemberMemoryInputSchema = inputObject.extend({
  evidence: z.enum(["self_reported", "operator_confirmed", "observed", "inferred"]),
}).superRefine(validateKind);
export type MemberMemoryInput = z.infer<typeof MemberMemoryInputSchema>;

/** Immutable ledger entry. Optional fields are omitted; project_id is always explicit. */
export const MemberMemoryEventSchema = inputObject.extend({
  // Imported legacy text is preserved even when old writers bypassed today's limit.
  text: z.string(),
  id: z.string().uuid(),
  seq: z.number().int().positive(),
  member_id: z.string().uuid(),
  recorded_at: timestamp,
  /** Original legacy log timestamp, including strings that were never valid dates. */
  legacy_at: z.string().optional(),
  /** Exact old source string, or JSON representation of a non-string source. */
  legacy_source: z.string().optional(),
}).strict().superRefine((value, ctx) => {
  validateKind(value, ctx);
  if (value.evidence !== "legacy" && !shape.text.safeParse(value.text).success) {
    ctx.addIssue({ code: z.ZodIssueCode.custom, path: ["text"], message: "text must be nonblank and at most 20000 characters" });
  }
});
export type MemberMemoryEvent = z.infer<typeof MemberMemoryEventSchema>;

/** Exact scope. current_facts includes all active assertions, including conflicts/inferences. */
export const MemberMemorySnapshotSchema = z.object({
  member_id: z.string().uuid(),
  project_id: z.string().min(1).nullable(),
  as_of: timestamp,
  current_facts: z.array(MemberMemoryEventSchema),
  conflicts: z.array(z.object({ fact_key: label, events: z.array(MemberMemoryEventSchema) }).strict()),
  open_commitments: z.array(MemberMemoryEventSchema),
  timeline: z.array(MemberMemoryEventSchema),
  total_events: z.number().int().nonnegative(),
  next_before_seq: z.number().int().positive().nullable(),
}).strict();
export type MemberMemorySnapshot = z.infer<typeof MemberMemorySnapshotSchema>;
