/**
 * Client project access (2026-10-02): what an external client lead may see of
 * their own project, and the immutable version-review ledger that binds an
 * acceptance to one authenticated member, one project and one exact published
 * version.
 *
 * Authority model (TheNexus db/client-access.js, server/routes/client-access.js):
 *  - An entitlement is an explicit, project-scoped grant for one member. It is
 *    honored only while the member is active, still linked to the project and
 *    unchanged since the grant, and the entitlement is not revoked. It never
 *    implies operator or administrative rights and never reaches another project.
 *  - The client surface (`/api/client-access/members/:memberId/projects...`) is
 *    callable only by the trusted runtime bearer credential. The runtime resolves
 *    the member from the member's own authenticated portal session; identity is
 *    never taken from a query parameter, a claimed name or an email.
 *  - `comment` and `request_changes` are feedback. Only `accept` is acceptance,
 *    and it is replay-safe (`client_decision_id`) and bound to `version_hash`.
 *    Acceptance is distinct from technical QA, document-review comments and
 *    Robert's reserved scope, capability, spending and release decisions; it
 *    changes no task, checkpoint, gate or proposal by itself.
 */

import { z } from "zod";

/**
 * Contract revision. 1.0: initial foundation. 1.1 (2026-10-02 QA repair):
 * credential-free link rule (`ClientSafeUrlSchema`), every acknowledged
 * `client_decision_id` reserved against its payload, identical publish retries
 * recognized before supersession rules, and fail-closed entitlement lookups
 * (`entitlement_unavailable`). Consumers may assert on this value.
 */
export const CLIENT_ACCESS_CONTRACT_REVISION = "1.1" as const;

export const CLIENT_ACCESS_SCOPE = "client_project" as const;
export const CLIENT_REVIEW_EVIDENCE_PREFIX = "nexus:client-review:" as const;

/**
 * The only link shape a client may receive or a publisher may submit: an
 * absolute http(s) URL with no embedded credentials. The server drops
 * anything else from project settings on projection and refuses it on
 * publication (`unsafe_url`); `javascript:`, `file:`, relative values and
 * `user:pass@host` forms never reach a client.
 */
export const ClientSafeUrlSchema = z
  .string()
  .max(2000)
  .refine(
    (value) => {
      try {
        const url = new URL(value);
        return (url.protocol === "http:" || url.protocol === "https:") && !url.username && !url.password;
      } catch {
        return false;
      }
    },
    { message: "must be an absolute http(s) URL without embedded credentials" },
  );

/**
 * Every `code` the client-access routes emit with a non-2xx status. A consumer
 * must treat `not_entitled` and `entitlement_unavailable` as "stop serving this
 * project to this member now"; neither a retained feed, snapshot nor cached
 * object may stand in for a current answer.
 */
export const CLIENT_ACCESS_ERROR_CODES = [
  "not_entitled",
  "entitlement_unavailable",
  "session_required",
  "session_invalid",
  "session_expired",
  "artifact_not_found",
  "version_mismatch",
  "artifact_not_current",
  "already_accepted",
  "decision_conflict",
  "unsafe_url",
  "publish_conflict",
  "artifact_already_superseded",
  "document_project_mismatch",
  "document_revision_missing",
  "document_revision_mismatch",
  "selection_required", "invalid_selection", "asset_changed", "asset_not_found", "invalid_asset_key", "asset_too_large",
] as const;
export const ClientAccessErrorCodeSchema = z.enum(CLIENT_ACCESS_ERROR_CODES);
export type ClientAccessErrorCode = z.infer<typeof ClientAccessErrorCodeSchema>;

/** Error body of the client-access routes; `code` is absent on plain validation errors. */
export const ClientAccessErrorSchema = z.object({
  error: z.string(),
  code: ClientAccessErrorCodeSchema.optional(),
});
export type ClientAccessError = z.infer<typeof ClientAccessErrorSchema>;

/** Headers the runtime adds to assert the authenticated portal session it acts for. */
export const CLIENT_SESSION_HEADERS = {
  sha256: "x-client-session-sha256",
  expires: "x-client-session-expires",
} as const;

const Sha256HexSchema = z.string().regex(/^[0-9a-f]{64}$/);

export const ClientArtifactKindSchema = z.enum(["document", "preview", "code", "deliverable"]);
export type ClientArtifactKind = z.infer<typeof ClientArtifactKindSchema>;

export const ClientArtifactStateSchema = z.enum(["current", "superseded", "withdrawn"]);
export type ClientArtifactState = z.infer<typeof ClientArtifactStateSchema>;

export const ClientReviewDecisionSchema = z.enum(["comment", "request_changes", "accept"]);
export type ClientReviewDecision = z.infer<typeof ClientReviewDecisionSchema>;

/** The identity an entitlement or review is bound to (captured at grant / review time). */
export const ClientMemberIdentitySchema = z.object({
  id: z.string(),
  name: z.string(),
  email: z.string().nullable(),
});
export type ClientMemberIdentity = z.infer<typeof ClientMemberIdentitySchema>;

export const ClientEntitlementStateSchema = z.enum(["active", "revoked"]);

export const ClientEntitlementSchema = z.object({
  id: z.string(),
  member_id: z.string(),
  project_id: z.string(),
  scope: z.literal(CLIENT_ACCESS_SCOPE),
  member_snapshot: ClientMemberIdentitySchema,
  granted_by: z.string(),
  /** `operator_credential` (Robert's bearer key) or `operator_local` (script run on the Nexus host). */
  authority: z.string(),
  source: z.string().nullable(),
  note: z.string().nullable(),
  granted_at: z.string(),
  state: ClientEntitlementStateSchema,
  revoked: z
    .object({ at: z.string(), reason: z.string().nullable(), by: z.string().nullable(), authority: z.string().nullable() })
    .nullable()
    .optional(),
});
export type ClientEntitlement = z.infer<typeof ClientEntitlementSchema>;

export const ClientDesignSelectionSchema = z.object({ direction: z.string().min(1).max(80) }).strict();
export const ClientMediaSchema = z.object({
  media_type: z.string(),
  directions: z.array(z.object({ id: z.string(), title: z.string(), summary: z.string().optional(), recommended: z.boolean().optional() })),
  assets: z.array(z.object({
    asset_key: z.string(), role: z.string(), media_type: z.string(), mime_type: z.string(), content_hash: Sha256HexSchema, byte_length: z.number(),
    label: z.string().nullable().optional(), direction: z.string().nullable().optional(), appearance: z.string().nullable().optional(),
    viewport: z.string().nullable().optional(), state: z.string().nullable().optional(), before_asset_key: z.string().nullable().optional(),
    width: z.number().nullable().optional(), height: z.number().nullable().optional(), order: z.number().optional(),
  })),
});

/**
 * Where a client's pinned note sits in the work (review room, 2026-10-16).
 * The vocabulary mirrors the internal reviewer's anchors
 * (review-media-and-design-packages.md §3): a region of an image or design
 * screen, a point on a prototype, a moment in video or audio, a page of a
 * PDF, a passage of a written document, or the document as a whole.
 */
const unit = z.number().min(0).max(1);
const AssetKeySchema = z.string().regex(/^[A-Za-z0-9._:-]{1,160}$/);
export const ClientCommentAnchorSchema = z.discriminatedUnion("kind", [
  z.object({ kind: z.literal("region"), asset_key: AssetKeySchema, x: unit, y: unit, w: unit.refine((v) => v > 0), h: unit.refine((v) => v > 0) }).strict(),
  z.object({ kind: z.literal("screen"), asset_key: AssetKeySchema, region: z.object({ x: unit, y: unit, w: unit.refine((v) => v > 0), h: unit.refine((v) => v > 0) }).strict() }).strict(),
  z.object({ kind: z.literal("point"), asset_key: AssetKeySchema, x: unit, y: unit, viewport: z.string().max(40).optional() }).strict(),
  z.object({ kind: z.literal("time"), asset_key: AssetKeySchema, t_start: z.number().min(0).max(360000), t_end: z.number().min(0).max(360000).optional() }).strict(),
  z.object({ kind: z.literal("page"), asset_key: AssetKeySchema, page: z.number().int().min(1).max(100000) }).strict(),
  z.object({ kind: z.literal("passage"), block: z.number().int().min(0).max(100000), quote: z.string().max(120).optional() }).strict(),
  z.object({ kind: z.literal("document") }).strict(),
]);
export type ClientCommentAnchor = z.infer<typeof ClientCommentAnchorSchema>;

/** One pinned note: the anchor, the human address the reviewer saw, and the words. */
export const ClientReviewCommentSchema = z.object({
  anchor: ClientCommentAnchorSchema,
  target_label: z.string().max(120).optional(),
  body: z.string().min(1).max(4000),
}).strict();
export type ClientReviewComment = z.infer<typeof ClientReviewCommentSchema>;

export const ClientReviewSchema = z.object({
  id: z.string(),
  /**
   * Caller-chosen idempotency key. Every acknowledged key (including one that
   * resolved to an existing acceptance) is reserved against its payload: an
   * identical replay returns the same review, any other reuse is 409
   * `decision_conflict`.
   */
  client_decision_id: z.string(),
  member: ClientMemberIdentitySchema,
  artifact_id: z.string(),
  version_hash: Sha256HexSchema,
  decision: ClientReviewDecisionSchema,
  body: z.string(),
  selection: ClientDesignSelectionSchema.optional(),
  /** Pinned notes recorded with the decision, in the order the client gave them. */
  comments: z.array(ClientReviewCommentSchema).optional(),
  created_at: z.string(),
  /** `nexus:client-review:<id>`: cite this as the checkpoint-criterion observation evidence. */
  evidence_ref: z.string(),
});
export type ClientReview = z.infer<typeof ClientReviewSchema>;

export const ClientArtifactSchema = z.object({
  id: z.string(),
  project_id: z.string(),
  kind: ClientArtifactKindSchema,
  media: ClientMediaSchema.optional(),
  title: z.string(),
  /** Human-readable version label (build id, commit, document revision prefix). */
  version: z.string(),
  /** sha256 of the canonical artifact identity; acceptance must quote it exactly. */
  version_hash: Sha256HexSchema,
  /** Re-checked on every read: a stored link that is not credential-free http(s) projects as null. */
  url: ClientSafeUrlSchema.nullable(),
  document: z
    .object({ id: z.string(), title: z.string().nullable(), revision_id: z.string().nullable(), content_hash: z.string().nullable() })
    .nullable(),
  checkpoint_id: z.string().nullable(),
  task_id: z.string().nullable(),
  notes: z.string().nullable(),
  supersedes_id: z.string().nullable(),
  superseded_by: z.string().nullable(),
  state: ClientArtifactStateSchema,
  published_by: z.string(),
  authority: z.string(),
  published_at: z.string(),
  withdrawn: z
    .object({ at: z.string(), reason: z.string().nullable(), by: z.string().nullable(), authority: z.string().nullable() })
    .nullable()
    .optional(),
  reviews: z.array(ClientReviewSchema),
  /** Accept decisions whose version_hash equals this artifact's version_hash. */
  accepted: z.array(ClientReviewSchema),
});
export type ClientArtifact = z.infer<typeof ClientArtifactSchema>;

export const ClientTaskProgressSchema = z.object({
  id: z.string(),
  name: z.string(),
  status: z.string(),
  priority: z.number(),
  created_at: z.string(),
  updated_at: z.string().nullable(),
  last_activity_at: z.string().nullable(),
  /** Optional client-safe summary a steward sets as `metadata.client_summary`; never the task description or prompts. */
  summary: z.string().nullable(),
  checkpoint_id: z.string().nullable(),
  /** Stakeholder gate status when the task is a client request awaiting a decision. */
  request_status: z.string().nullable(),
});
export type ClientTaskProgress = z.infer<typeof ClientTaskProgressSchema>;

export const ClientRequirementsSchema = z.object({
  end_state: z.string().nullable(),
  end_state_updated_at: z.string().nullable(),
  criteria: z.array(z.object({ id: z.string(), description: z.string(), kind: z.string().nullable(), enabled: z.boolean() })),
  needs: z.array(
    z.object({
      id: z.string(),
      kind: z.string().nullable(),
      description: z.string(),
      status: z.string(),
      blocking: z.boolean(),
      question: z.string().nullable(),
      satisfaction_test: z.string().nullable(),
      created_at: z.string().nullable(),
    }),
  ),
});
export type ClientRequirements = z.infer<typeof ClientRequirementsSchema>;

export const ClientCheckpointSchema = z.object({
  id: z.string(),
  title: z.string(),
  goal: z.string(),
  status: z.string(),
  current: z.boolean(),
  completed_at: z.string().nullable(),
  criteria: z.array(z.object({ id: z.string(), description: z.string(), kind: z.string().nullable() })),
});
export type ClientCheckpoint = z.infer<typeof ClientCheckpointSchema>;

/** GET /api/client-access/members/:memberId/projects/:projectId */
export const ClientProjectWorkspaceSchema = z.object({
  generated_at: z.string(),
  member: ClientMemberIdentitySchema,
  entitlement: z.object({ id: z.string(), scope: z.literal(CLIENT_ACCESS_SCOPE), granted_at: z.string() }),
  membership: z.object({ role: z.string().nullable(), decision_maker: z.boolean() }),
  project: z.object({
    id: z.string(),
    name: z.string(),
    description: z.string().nullable(),
    status: z.string(),
    /** Allowlisted keys, credential-free http(s) values only; anything else in project settings is dropped. */
    urls: z.object({ production: ClientSafeUrlSchema.optional(), repo: ClientSafeUrlSchema.optional(), docs: ClientSafeUrlSchema.optional() }),
    created_at: z.string().nullable(),
    updated_at: z.string().nullable(),
  }),
  requirements: ClientRequirementsSchema,
  checkpoints: z.object({
    current_id: z.string().nullable(),
    sequence_completed_at: z.string().nullable(),
    items: z.array(ClientCheckpointSchema),
  }),
  tasks: z.array(ClientTaskProgressSchema),
  artifacts: z.array(ClientArtifactSchema),
  /** Accept decisions across the project's artifacts. */
  decisions: z.array(ClientReviewSchema),
  /** Comments and change requests. */
  feedback: z.array(ClientReviewSchema),
  session: z.object({ expires_at: z.string() }).nullable().optional(),
});
export type ClientProjectWorkspace = z.infer<typeof ClientProjectWorkspaceSchema>;

/** GET /api/client-access/members/:memberId/projects */
export const ClientProjectListSchema = z.object({
  member_id: z.string(),
  projects: z.array(
    z.object({
      id: z.string(),
      name: z.string(),
      status: z.string(),
      granted_at: z.string(),
      entitlement_id: z.string(),
      role: z.string().nullable(),
    }),
  ),
  session: z.object({ expires_at: z.string() }).nullable().optional(),
});
export type ClientProjectList = z.infer<typeof ClientProjectListSchema>;

/** GET .../artifacts/:artifactId: the artifact plus captured document content for `document` kinds. */
export const ClientArtifactDetailSchema = z.object({
  artifact: ClientArtifactSchema,
  media: ClientMediaSchema.optional(),
  content: z
    .object({ content: z.string(), content_hash: z.string(), byte_length: z.number(), line_count: z.number(), captured_at: z.string() })
    .nullable(),
});
export type ClientArtifactDetail = z.infer<typeof ClientArtifactDetailSchema>;

/** What the runtime asserts about the portal session it acts for (header values). */
export const ClientSessionAssertionSchema = z.object({
  sha256: Sha256HexSchema,
  expires_at: z.string(),
});
export type ClientSessionAssertion = z.infer<typeof ClientSessionAssertionSchema>;

/** POST .../artifacts/:artifactId/reviews body. */
export const ClientReviewRequestSchema = z.object({
  client_decision_id: z.string().min(1).max(200),
  decision: ClientReviewDecisionSchema,
  version_hash: Sha256HexSchema,
  /** Required for comment / request_changes unless pinned notes are present; optional for accept. */
  body: z.string().max(20000).optional(),
  selection: ClientDesignSelectionSchema.optional(),
  /** Pinned notes, each anchored to a place in the work. */
  comments: z.array(ClientReviewCommentSchema).max(50).optional(),
});
export type ClientReviewRequest = z.infer<typeof ClientReviewRequestSchema>;

export const ClientReviewResponseSchema = z.object({
  review: ClientReviewSchema,
  artifact: ClientArtifactSchema,
  duplicate: z.boolean(),
  evidence_ref: z.string(),
});
export type ClientReviewResponse = z.infer<typeof ClientReviewResponseSchema>;

/** POST /api/projects/:id/client-access/artifacts body (runtime or operator credential). */
export const ClientArtifactPublishSchema = z.object({
  kind: ClientArtifactKindSchema,
  title: z.string().min(1).max(300),
  /** Required for preview / code / deliverable; defaults to the content-hash prefix for documents. */
  version: z.string().max(200).optional(),
  document_id: z.string().optional(),
  /** Defaults to the document's current captured revision. */
  revision_id: z.string().optional(),
  /** Required for preview / code; credential-free absolute http(s) only (server: 400 `unsafe_url`). */
  url: ClientSafeUrlSchema.optional(),
  checkpoint_id: z.string().optional(),
  task_id: z.string().optional(),
  notes: z.string().max(4000).optional(),
  supersedes_id: z.string().optional(),
});
export type ClientArtifactPublish = z.infer<typeof ClientArtifactPublishSchema>;

/** POST /api/projects/:id/client-access/entitlements body (operator credential only). */
export const ClientEntitlementGrantSchema = z.object({
  member_id: z.string().min(1),
  source: z.string().max(1000).optional(),
  note: z.string().max(2000).optional(),
});
export type ClientEntitlementGrant = z.infer<typeof ClientEntitlementGrantSchema>;

export const clientReviewEvidenceRef = (reviewId: string): string => `${CLIENT_REVIEW_EVIDENCE_PREFIX}${reviewId}`;

export const clientReviewIdFromEvidenceRef = (ref: string): string | null =>
  typeof ref === "string" && ref.startsWith(CLIENT_REVIEW_EVIDENCE_PREFIX) && ref.length > CLIENT_REVIEW_EVIDENCE_PREFIX.length
    ? ref.slice(CLIENT_REVIEW_EVIDENCE_PREFIX.length)
    : null;
