/**
 * Checkpoint selection and scoping helpers shared by TheNexus (persistence
 * and the advancement transition), the dashboard (progress display) and
 * Praxis (steward verification, planning). The schemas live in project.ts;
 * this module holds the pure functions so every consumer picks the same
 * current checkpoint and scopes requirements the same way.
 *
 * A project's long-term goal stays in `end_state` / `end_state_criteria`.
 * When a checkpoint plan exists, the CURRENT checkpoint (first pending item
 * in order) is the effective endpoint: its goal and criteria drive planning,
 * knowledge needs, task targeting and verification until fresh evidence
 * verifies it. Final-goal criteria and needs linked to no checkpoint are
 * project-wide requirements that gate final completion, not intermediate
 * advancement.
 */
import {
  CheckpointPlanSchema,
  type Checkpoint,
  type CheckpointPlan,
  type EndStateCriterion,
} from "./project.js";

/** Lenient need view: legacy needs and Praxis wire records need not carry every contract field. */
export interface CheckpointNeedLike {
  id: string;
  kind: string;
  status: string;
  knowledge?: {
    blocking?: boolean;
    criterion_ids?: string[];
    research_status?: string;
    verified_at?: string;
    answer?: string;
    evidence?: Array<{ ref: string }>;
    endpoint_revision?: string;
  };
}

/** Parse a stored plan leniently: absent or malformed plans read as "no checkpoints". */
export function parseCheckpointPlan(value: unknown): CheckpointPlan | null {
  if (!value || typeof value !== "object") return null;
  const parsed = CheckpointPlanSchema.safeParse(value);
  return parsed.success ? parsed.data : null;
}

/** Ordered plan items that are part of the live sequence (archived rows never are). */
export function activeCheckpoints(plan: CheckpointPlan | null | undefined): Checkpoint[] {
  return (plan?.items ?? []).filter(item => item.status !== "archived");
}

/** The effective endpoint right now: the first pending checkpoint in order, or null. */
export function currentCheckpoint(plan: CheckpointPlan | null | undefined): Checkpoint | null {
  return activeCheckpoints(plan).find(item => item.status === "pending") ?? null;
}

export interface CheckpointProgress {
  total: number;
  completed: Checkpoint[];
  current: Checkpoint | null;
  upcoming: Checkpoint[];
  /** True only when the plan has items and every item is completed. */
  sequenceComplete: boolean;
}

export function checkpointProgress(plan: CheckpointPlan | null | undefined): CheckpointProgress {
  const items = activeCheckpoints(plan);
  const current = currentCheckpoint(plan);
  const currentIndex = current ? items.indexOf(current) : items.length;
  return {
    total: items.length,
    completed: items.filter(item => item.status === "completed"),
    current,
    upcoming: current ? items.slice(currentIndex + 1).filter(item => item.status === "pending") : [],
    sequenceComplete: items.length > 0 && items.every(item => item.status === "completed"),
  };
}

/** Enabled criteria of one checkpoint (disabled rows count neither for nor against it). */
export function checkpointCriteria(checkpoint: Pick<Checkpoint, "criteria">): EndStateCriterion[] {
  return (checkpoint.criteria ?? []).filter(criterion => criterion.enabled !== false);
}

/** A need is scoped to a checkpoint through need_ids or through a criterion the checkpoint owns. */
export function checkpointLinksNeed(
  checkpoint: Pick<Checkpoint, "need_ids" | "criteria">,
  need: CheckpointNeedLike,
): boolean {
  if ((checkpoint.need_ids ?? []).includes(need.id)) return true;
  const owned = new Set((checkpoint.criteria ?? []).map(criterion => criterion.id));
  return (need.knowledge?.criterion_ids ?? []).some(id => owned.has(id));
}

function informationNeeds<T extends CheckpointNeedLike>(needs: T[]): T[] {
  return needs.filter(need => need.kind === "information" && need.status !== "dropped" && need.knowledge);
}

/** Information needs linked to this checkpoint (required or optional). */
export function checkpointScopedNeeds<T extends CheckpointNeedLike>(
  checkpoint: Pick<Checkpoint, "need_ids" | "criteria">,
  needs: T[],
): T[] {
  return informationNeeds(needs).filter(need => checkpointLinksNeed(checkpoint, need));
}

/** Blocking information needs that gate THIS checkpoint. */
export function checkpointRequiredNeeds<T extends CheckpointNeedLike>(
  checkpoint: Pick<Checkpoint, "need_ids" | "criteria">,
  needs: T[],
): T[] {
  return checkpointScopedNeeds(checkpoint, needs).filter(need => need.knowledge?.blocking);
}

/**
 * Blocking information needs linked to no live checkpoint. These are
 * project-wide requirements: they gate final completion and stay visible, but
 * an early checkpoint does not wait on them.
 */
export function projectWideRequiredNeeds<T extends CheckpointNeedLike>(
  plan: CheckpointPlan | null | undefined,
  needs: T[],
): T[] {
  const items = activeCheckpoints(plan);
  return informationNeeds(needs).filter(need =>
    need.knowledge?.blocking && !items.some(item => checkpointLinksNeed(item, need)));
}

/** Present work may use global needs and current links; future-only links are deferred. */
export function currentWorkNeeds<T extends CheckpointNeedLike>(plan: CheckpointPlan | null | undefined, needs: T[]): T[] {
  const current = currentCheckpoint(plan);
  if (!current) return needs;
  return needs.filter(need => checkpointLinksNeed(current, need) || !activeCheckpoints(plan).some(cp => checkpointLinksNeed(cp, need)));
}

/** Matches the runtime's evidence and endpoint revision requirements for a satisfied need. */
export function knowledgeSatisfied(need: CheckpointNeedLike, revision?: string | null): boolean {
  const k = need.knowledge;
  return Boolean(
    k && need.status === "met" && k.research_status !== "stale" &&
    k.verified_at && Number.isFinite(Date.parse(k.verified_at)) && k.answer?.trim() &&
    k.evidence?.some(e => e.ref?.trim()) &&
    (!revision || !k.endpoint_revision || k.endpoint_revision === revision),
  );
}

export interface KnowledgeProgress {
  required: number;
  satisfied: number;
  unresolved: number;
  open_ids: string[];
}

/** Progress over an already-scoped set of required needs. */
export function knowledgeProgress(required: CheckpointNeedLike[], revision?: string | null): KnowledgeProgress {
  const open = required.filter(need => !knowledgeSatisfied(need, revision));
  return { required: required.length, satisfied: required.length - open.length, unresolved: open.length, open_ids: open.map(need => need.id) };
}

export interface VerdictAssessment {
  results: Array<{ id: string; status?: string; pass?: boolean }>;
  knowledge: { unresolved: number };
}

/**
 * The server-side verdict rule. Every enabled criterion needs a fresh result
 * with status "pass"; at least one criterion must exist (an empty or fully
 * disabled criteria set can never complete a checkpoint); and no applicable
 * required knowledge may be unresolved. fail / unknown / unverifiable results
 * and skipped tasks (reported as fail) all leave the checkpoint current.
 */
export function assessmentVerifies(assessment: VerdictAssessment, criteria: EndStateCriterion[]): boolean {
  const enabled = criteria.filter(criterion => criterion.enabled !== false);
  if (enabled.length === 0 || assessment.results.length === 0) return false;
  if (assessment.knowledge.unresolved > 0) return false;
  const byId = new Map(assessment.results.map(result => [result.id, result]));
  return enabled.every(criterion => {
    const result = byId.get(criterion.id);
    return Boolean(result && result.pass !== false && (result.status ?? (result.pass ? "pass" : "fail")) === "pass");
  });
}

export interface EffectiveEndpoint {
  /** "checkpoint" while a plan has a current item; "final" for the long-term goal alone; "none" without any goal. */
  kind: "checkpoint" | "final" | "none";
  /** The text planning and verification target right now. */
  goal: string;
  /** The project's long-term end state, always retained. */
  longTermGoal: string;
  /** Criteria that verify the effective endpoint. */
  criteria: EndStateCriterion[];
  checkpoint: Checkpoint | null;
  progress: CheckpointProgress;
}

export function effectiveEndpoint(project: {
  end_state?: string | null;
  end_state_criteria?: EndStateCriterion[] | null;
  checkpoints?: CheckpointPlan | null;
}): EffectiveEndpoint {
  const longTermGoal = (project.end_state ?? "").trim();
  const progress = checkpointProgress(project.checkpoints);
  if (progress.current) {
    return {
      kind: "checkpoint",
      goal: progress.current.goal.trim() || progress.current.title.trim(),
      longTermGoal,
      criteria: checkpointCriteria(progress.current),
      checkpoint: progress.current,
      progress,
    };
  }
  return {
    kind: longTermGoal ? "final" : "none",
    goal: longTermGoal,
    longTermGoal,
    criteria: (project.end_state_criteria ?? []).filter(criterion => criterion.enabled !== false),
    checkpoint: null,
    progress,
  };
}

/** One-line sequence summary for prompts and logs. */
export function describeCheckpointSequence(plan: CheckpointPlan | null | undefined): string {
  const progress = checkpointProgress(plan);
  if (progress.total === 0) return "No checkpoints defined; the long-term end state is the effective endpoint.";
  if (progress.sequenceComplete) return `All ${progress.total} checkpoint(s) verified; the long-term end state is now the effective endpoint.`;
  const position = progress.completed.length + 1;
  const upcoming = progress.upcoming.map(item => item.title).join(" -> ");
  return `Checkpoint ${position} of ${progress.total} is current: "${progress.current!.title}".` +
    (upcoming ? ` Upcoming: ${upcoming}.` : " It is the final checkpoint.");
}
