import { z } from "zod";
import { ProjectCommsSettingsSchema, ReportTemplateSchema } from "./stakeholders.js";

/**
 * Project lifecycle status.
 *
 * - `active`    — full participation: scheduling, goal regression, tagging,
 *                 council/knowledge task filing.
 * - `parked`    — deliberately dormant. Excluded from every autonomous surface
 *                 (morning scheduling, goal regression, project tagging,
 *                 council APPLY/slate filing) but stays visible on the board
 *                 with all data retained. Robert's "not now, keep everything"
 *                 state.
 * - `paused`    — temporarily on hold; mechanically identical to `parked`
 *                 (only `active`/unset projects participate), softer intent.
 * - `completed` — reached its end state; kept for the record.
 * - `archived`  — hidden from the board and context retrieval (see
 *                 TheNexus archiveProject).
 */
export const ProjectStatusSchema = z.enum([
  "active",
  "parked",
  "paused",
  "completed",
  "archived",
]);
export type ProjectStatus = z.infer<typeof ProjectStatusSchema>;

/**
 * How much autonomous improvement attention a project accepts. Orthogonal to
 * `status` (gates WHAT the system may file, status gates WHETHER it looks at
 * the project at all — non-active projects are skipped regardless of posture).
 *
 * - `auto`    — councils / knowledge routing / steward may file improvement
 *               tasks, and the morning pipeline may schedule them through the
 *               normal approval flow. Default.
 * - `propose` — system-sourced tasks may be FILED (visible on the board as
 *               ideas) but are never auto-scheduled; Robert promotes them.
 * - `off`     — no autonomous improvement filings at all. Robert-created
 *               tasks still schedule normally.
 */
export const UpgradePostureSchema = z.enum(["auto", "propose", "off"]);
export type UpgradePosture = z.infer<typeof UpgradePostureSchema>;

export const ProjectNeedKindSchema = z.enum([
  "capability", // something the system must be able to DO (missing component)
  "resource",   // compute, money, hardware, a service subscription
  "credential", // API key, OAuth grant, account — Robert must provision
  "decision",   // a human call that blocks progress
  "information",// knowledge that must be hunted/learned first
]);
export type ProjectNeedKind = z.infer<typeof ProjectNeedKindSchema>;

const NonemptyTextSchema = z.string().refine(value => value.trim().length > 0, "Must not be blank");
const EvidenceDateSchema = z.string().datetime({ offset: true });

export const KnowledgeEvidenceSchema = z.object({
  ref: NonemptyTextSchema,
  summary: z.string().optional(),
  checked_at: EvidenceDateSchema.optional(),
});
export type KnowledgeEvidence = z.infer<typeof KnowledgeEvidenceSchema>;

export const KnowledgeApplicationSchema = z.object({
  status: z.enum(["untried", "successful", "insufficient", "outdated"]),
  task_id: z.string().optional(),
  at: EvidenceDateSchema.optional(),
  evidence_ref: NonemptyTextSchema.optional(),
  notes: z.string().optional(),
});
export type KnowledgeApplication = z.infer<typeof KnowledgeApplicationSchema>;

/** Evidence-bearing question; satisfaction is an explicit server transition. */
export const KnowledgeNeedSchema = z.object({
  question: NonemptyTextSchema,
  tags: z.array(z.string().transform(tag => tag.trim().replace(/^#+/, "").toLowerCase()
    .replace(/[^a-z0-9]+/g, "-").replace(/^-|-$/g, ""))
    .pipe(z.string().min(1))).default([]).transform(tags => [...new Set(tags)]),
  satisfaction_test: NonemptyTextSchema,
  criterion_ids: z.array(NonemptyTextSchema).default([]),
  task_ids: z.array(NonemptyTextSchema).default([]),
  blocking: z.boolean().default(false),
  research_status: z.enum(["open", "researching", "evidence_ready", "stale"]).default("open"),
  answer: z.string().optional(),
  evidence: z.array(KnowledgeEvidenceSchema).default([]),
  endpoint_revision: z.string().optional(),
  verified_at: z.string().optional(),
  verified_by: z.string().optional(),
  review_reason: z.string().optional(),
  application: KnowledgeApplicationSchema.optional(),
});
export type KnowledgeNeed = z.infer<typeof KnowledgeNeedSchema>;

export const EndpointDefinitionSchema = z.object({
  beneficiary: z.string().optional(),
  scope: z.string().optional(),
  exclusions: z.string().optional(),
  resource_budget: z.string().optional(),
  review_at: z.string().optional(),
  completion_policy: z.enum(["complete", "maintain", "park", "propose_next"]).default("propose_next"),
  proposed_next: z.string().optional(),
});
export type EndpointDefinition = z.infer<typeof EndpointDefinitionSchema>;

/**
 * A declared need: something the project is missing on the way to its end
 * state. Open needs are the machine-readable "what is missing" registry —
 * councils and the steward read them to aim improvement work, and resolving
 * one is itself schedulable work.
 */
export const ProjectNeedSchema = z.object({
  id: z.string(),
  kind: ProjectNeedKindSchema,
  description: z.string(),
  status: z.enum(["open", "met", "dropped"]).default("open"),
  created_at: z.string(),
  resolved_at: z.string().optional(),
  /** Who declared it: "robert", "council", "steward", an agent/session name. */
  source: z.string().optional(),
  notes: z.string().optional(),
  knowledge: KnowledgeNeedSchema.optional(),
}).refine(need => !need.knowledge || need.kind === "information", {
  message: "Only information needs can carry knowledge", path: ["knowledge"],
});
export type ProjectNeed = z.infer<typeof ProjectNeedSchema>;

/**
 * Machine-checkable end-state acceptance criteria. The Project Data Steward
 * evaluates the safe kinds on its weekly pass and cites per-criterion
 * pass/fail in `end_state_possibly_achieved` flags, replacing the bare
 * "no open tasks + ≥3 done" heuristic for projects that declare criteria.
 */
export const EndStateCriterionKindSchema = z.enum([
  "url_up",   // GET the url; pass when status is 200-399 (or expect_status)
  "command",  // run an allowlisted command in the project workspace; pass on exit 0
  "task_set", // pass when every task id listed is completed on the board
  "manual",
  "metric",
]);
export type EndStateCriterionKind = z.infer<typeof EndStateCriterionKindSchema>;

export const CriterionStatusSchema = z.enum(["pass", "fail", "unknown", "unverifiable"]);
export const MetricDefinitionSchema = z.object({
  baseline: z.number().finite().optional(),
  target: z.number().finite(),
  operator: z.enum(["gte", "lte", "eq"]),
  unit: z.string().optional(),
  window_days: z.number().positive().optional(),
  min_samples: z.number().int().positive().optional(),
});
export const CriterionObservationSchema = z.object({
  status: CriterionStatusSchema,
  observed_at: EvidenceDateSchema,
  evidence_ref: NonemptyTextSchema,
  value: z.number().finite().optional(),
  sample_size: z.number().int().nonnegative().optional(),
  detail: z.string().optional(),
});

export const EndStateCriterionSchema = z.object({
  id: z.string(),
  kind: EndStateCriterionKindSchema,
  /** Human label — what this criterion proves about the end state. */
  description: z.string(),
  /** url_up: the URL to probe. */
  url: z.string().optional(),
  /** url_up: exact HTTP status expected (default: any 2xx/3xx). */
  expect_status: z.number().int().optional(),
  /** command: run from the project workspace; evaluator enforces an allowlist. */
  command: z.string().optional(),
  /** task_set: board task ids that must all be completed. */
  task_ids: z.array(z.string()).optional(),
  enabled: z.boolean().default(true),
  created_at: z.string().optional(),
  /** Who declared it: "robert", "steward-proposal", an agent/session name. */
  source: z.string().optional(),
  metric: MetricDefinitionSchema.optional(),
  observation: CriterionObservationSchema.optional(),
}).superRefine((criterion, ctx) => {
  if (criterion.kind === "metric" && !criterion.metric) {
    ctx.addIssue({ code: "custom", path: ["metric"], message: "Metric criteria require a target and operator" });
  }
  if (criterion.kind === "metric" && criterion.observation && criterion.observation.value === undefined) {
    ctx.addIssue({ code: "custom", path: ["observation", "value"], message: "Metric observations require a numeric value" });
  }
});
export type EndStateCriterion = z.infer<typeof EndStateCriterionSchema>;

export const EndStateCriterionResultSchema = z.object({
  id: z.string(),
  description: z.string().optional(),
  kind: EndStateCriterionKindSchema.optional(),
  pass: z.boolean(),
  status: CriterionStatusSchema,
  checked_at: EvidenceDateSchema,
  detail: z.string().optional(),
  value: z.number().finite().optional(),
  sample_size: z.number().int().nonnegative().optional(),
  evidence_ref: z.string().optional(),
});
export type EndStateCriterionResult = z.infer<typeof EndStateCriterionResultSchema>;
export const EndStateAssessmentSchema = z.object({
  evaluated_at: EvidenceDateSchema,
  endpoint_revision: z.string().optional(),
  results: z.array(EndStateCriterionResultSchema),
  knowledge: z.object({
    required: z.number().int().nonnegative(),
    satisfied: z.number().int().nonnegative(),
    unresolved: z.number().int().nonnegative(),
  }),
  /**
   * Checkpoint sequence position at evaluation time. While a sequence is
   * incomplete the final goal cannot read as achieved, whatever its criteria
   * say; the summary makes that gate visible in the stored assessment.
   */
  checkpoints: z.object({
    current_id: z.string().nullable(),
    completed: z.number().int().nonnegative(),
    total: z.number().int().nonnegative(),
    sequence_complete: z.boolean(),
  }).optional(),
  achieved: z.boolean().optional(),
});
export type EndStateAssessment = z.infer<typeof EndStateAssessmentSchema>;

/**
 * One revision of a project's end state. `end_state_history` is the ordered
 * list of these (oldest first); the newest entry mirrors the live
 * `end_state`. Appended server-side by TheNexus on every end_state change so
 * end states can evolve without losing where they came from.
 */
export const EndStateRevisionSchema = z.object({
  end_state: z.string(),
  at: z.string(),
  /** Who set it: "robert", "steward-proposal", an agent/session name. */
  source: z.string().optional(),
  /** Why it changed — e.g. "previous horizon reached", "scope pivot". */
  reason: z.string().optional(),
  endpoint: EndpointDefinitionSchema.optional(),
  end_state_criteria: z.array(EndStateCriterionSchema).optional(),
});
export type EndStateRevision = z.infer<typeof EndStateRevisionSchema>;

/**
 * Ordered checkpoints under the long-term end state (Nexus 143abc00). The
 * first pending checkpoint in order is the effective endpoint until fresh
 * evidence verifies it; TheNexus then records the completion and the next
 * checkpoint becomes current, without touching `end_state`. Selection and
 * scoping helpers live in ./checkpoints.ts so every consumer agrees.
 */
export const CheckpointStatusSchema = z.enum(["pending", "completed", "archived"]);
export type CheckpointStatus = z.infer<typeof CheckpointStatusSchema>;

/** A checkpoint evaluation, bound to the exact definition it verified. */
export const CheckpointAssessmentSchema = EndStateAssessmentSchema.extend({
  checkpoint_id: z.string(),
  definition_revision: z.string(),
});
export type CheckpointAssessment = z.infer<typeof CheckpointAssessmentSchema>;

export const CheckpointCompletionSchema = z.object({
  at: EvidenceDateSchema,
  /** The definition revision the evidence verified; a later edit makes this completion historical. */
  definition_revision: z.string(),
  /** Who submitted the verifying evidence: "steward", "operator", an agent name. */
  source: z.string().optional(),
  assessment: CheckpointAssessmentSchema,
});
export type CheckpointCompletion = z.infer<typeof CheckpointCompletionSchema>;

/** Immutable definition attached to historical evidence. */
export const CheckpointSnapshotSchema = z.object({
  id: z.string(), title: z.string(), goal: z.string(),
  criteria: z.array(EndStateCriterionSchema), need_ids: z.array(z.string()),
});

export const CheckpointHistoryEventSchema = z.object({
  kind: z.enum(["completed", "reopened", "definition_changed", "archived", "restored"]),
  at: z.string(),
  definition_revision: z.string(),
  source: z.string().optional(),
  reason: z.string().optional(),
  definition: CheckpointSnapshotSchema.optional(),
  /** Retained evidence for completed / reopened events. */
  assessment: CheckpointAssessmentSchema.optional(),
});
export type CheckpointHistoryEvent = z.infer<typeof CheckpointHistoryEventSchema>;

/** The author-owned part of a checkpoint: what clients send when editing the plan. */
export const CheckpointDefinitionSchema = z.object({
  id: z.string(),
  title: NonemptyTextSchema,
  /** The checkpoint's own endpoint statement: what is observably true when it is reached. */
  goal: z.string().default(""),
  /** Acceptance criteria for THIS checkpoint (same kinds and evidence rules as end_state_criteria). */
  criteria: z.array(EndStateCriterionSchema).default([]),
  /** Information needs whose satisfaction this checkpoint requires when they are blocking. */
  need_ids: z.array(z.string()).default([]),
});
export type CheckpointDefinition = z.infer<typeof CheckpointDefinitionSchema>;

/** A stored checkpoint: the definition plus server-owned status, evidence and history. */
export const CheckpointSchema = CheckpointDefinitionSchema.extend({
  created_at: z.string(),
  /** Bumps whenever goal, criteria definitions or need_ids change. */
  definition_revision: z.string(),
  status: CheckpointStatusSchema.default("pending"),
  completion: CheckpointCompletionSchema.nullable().optional(),
  /** Latest evaluation of the current definition (waiting-for-evidence display). */
  assessment: CheckpointAssessmentSchema.nullable().optional(),
  history: z.array(CheckpointHistoryEventSchema).default([]),
  archived_at: z.string().optional(),
});
export type Checkpoint = z.infer<typeof CheckpointSchema>;

export const CheckpointPlanSchema = z.object({
  /** Ordered live sequence (pending or completed). */
  items: z.array(CheckpointSchema).default([]),
  /** Removed checkpoints, kept with their evidence and history. */
  archived: z.array(CheckpointSchema).default([]),
  /** Plan revision: bumps on every edit, reorder, removal, advance or reopen. Guard with expected_checkpoints_revision. */
  revision: z.string(),
  /** Set when the final checkpoint was verified; cleared by a reopen or a new pending checkpoint. */
  sequence_completed_at: z.string().nullable().optional(),
});
export type CheckpointPlan = z.infer<typeof CheckpointPlanSchema>;

export const ProjectHealthSchema = z.enum([
  "healthy",
  "needs-attention",
  "critical",
  "unknown",
]);
export type ProjectHealth = z.infer<typeof ProjectHealthSchema>;

export const GitCommitSummarySchema = z.object({
  hash: z.string(),
  message: z.string(),
  authorName: z.string(),
  authorEmail: z.string().optional(),
  timestamp: z.string().datetime(),
});
export type GitCommitSummary = z.infer<typeof GitCommitSummarySchema>;

export const GitStatusSummarySchema = z.object({
  hasGit: z.boolean(),
  hasRemote: z.boolean(),
  branch: z.string().nullable(),
  isClean: z.boolean(),
  ahead: z.number().int().nonnegative(),
  behind: z.number().int().nonnegative(),
  modifiedCount: z.number().int().nonnegative(),
  stagedCount: z.number().int().nonnegative(),
  untrackedCount: z.number().int().nonnegative(),
  daysSinceCommit: z.number().nullable().optional(),
  lastCommit: GitCommitSummarySchema.nullable().optional(),
});
export type GitStatusSummary = z.infer<typeof GitStatusSummarySchema>;

export const ProjectStatsSchema = z.object({
  openTaskCount: z.number().int().nonnegative().optional(),
  pendingReviewCount: z.number().int().nonnegative().optional(),
  blockedTaskCount: z.number().int().nonnegative().optional(),
});
export type ProjectStats = z.infer<typeof ProjectStatsSchema>;

export const ProjectUrlsSchema = z.object({
  production: z.string().url().optional(),
  repo: z.string().url().optional(),
  docs: z.string().url().optional(),
});
export type ProjectUrls = z.infer<typeof ProjectUrlsSchema>;

export const ProjectSchema = z.object({
  id: z.string(),
  name: z.string(),
  path: z.string(),
  description: z.string().optional(),

  status: ProjectStatusSchema.optional(),
  health: ProjectHealthSchema.optional(),

  pinnedAt: z.string().datetime().nullable().optional(),
  lastActiveAt: z.string().datetime().optional(),

  gitStatus: GitStatusSummarySchema.optional(),
  stats: ProjectStatsSchema.optional(),

  tags: z.array(z.string()).optional(),
  techStack: z.array(z.string()).optional(),

  type: z.string().optional(),
  vibe: z.string().optional(),
  urls: ProjectUrlsSchema.optional(),
  endState: z.string().optional(),
  endpoint: EndpointDefinitionSchema.optional(),
  endStateAssessment: EndStateAssessmentSchema.nullable().optional(),

  /** Attention priority: 0 = normal (default), >0 elevated, <0 backburner. */
  priority: z.number().int().optional(),
  upgradePosture: UpgradePostureSchema.optional(),
  needs: z.array(ProjectNeedSchema).optional(),
  endStateHistory: z.array(EndStateRevisionSchema).optional(),
  endStateCriteria: z.array(EndStateCriterionSchema).optional(),
  endStateUpdatedAt: z.string().datetime().optional(),
  /** Ordered checkpoints under the long-term end state; null/absent = no plan. */
  checkpoints: CheckpointPlanSchema.nullable().optional(),

  createdAt: z.string().datetime().optional(),
  updatedAt: z.string().datetime().optional(),
  completedAt: z.string().datetime().optional(),

  /** Stakeholder communication controls (status reports, recipients, cadence). */
  commsSettings: ProjectCommsSettingsSchema.optional(),
  /** The project's branded status-report template (created on first use). */
  reportTemplate: ReportTemplateSchema.optional(),

  metadata: z.record(z.string(), z.unknown()).optional(),
});
export type Project = z.infer<typeof ProjectSchema>;
